"""Export a frozen panel and copy references regenerated by the original FARE runners."""
from pathlib import Path
import argparse
import json
import os
import shutil
import sys
import numpy as np
from data_provider.panel import Panel
from exp.io import write_json, seal

HERE = Path(__file__).resolve().parent
REPRO = HERE.parent


def prepare(dataset, raw_root, reference_root, out):
    if out.exists():
        raise ValueError('Use a new panel output directory')
    if dataset in ['favorita', 'm5']:
        os.environ['FARE_RAW_ROOT'] = str(raw_root.resolve())
        from data_provider.retail import RetailData, schedules
        source = RetailData(dataset)
        schedule = schedules()['favorita_original' if dataset == 'favorita' else 'm5_full']
        values, ids, days = source.values, source.ids, source.days
        first = source.first.astype('datetime64[D]').astype(str).tolist()
        eligibility = None
    else:
        if dataset == 'rossmann':
            from data_provider.rossmann import RossmannData
            source = RossmannData(raw_root / dataset)
        else:
            from data_provider.rohlik import RohlikData
            source = RohlikData(raw_root / dataset)
        schedule = dict(source.schedule)
        schedule.update(train=schedule['fit'][:-8], tune=schedule['fit'][-8:])
        values, ids = source.arr['Sales'], source.ids
        days = source.dates.strftime('%Y-%m-%d').tolist()
        first = [days[0]] * len(ids)
        eligibility = {o: source.eligible(o, reference=o in schedule['fit']).tolist()
                       for split in ['fit', 'dev', 'test'] for o in schedule[split]}
    out.mkdir(parents=True)
    np.save(out / 'values.npy', values)
    meta = dict(dataset=dataset, schedule=schedule, ids=list(map(str, ids)), days=days, first=first)
    if eligibility is not None:
        meta['eligible_rows'] = eligibility
    write_json(out / 'panel.json', meta)
    (out / 'references').mkdir()
    provenance = {}
    for origin in schedule['dev'] + schedule['test']:
        path = reference_root / 'references' / f'{origin}.parquet'
        if not path.is_file():
            raise FileNotFoundError('Run the original reference stage first: ' + str(path))
        target = out / 'references' / path.name
        shutil.copy2(path, target)
        provenance[origin] = str(path)
    panel = Panel(out, check=False)
    write_json(out / 'audit.json', panel.audit())
    write_json(out / 'reference_provenance.json', provenance)
    seal(out, [p for p in out.rglob('*') if p.is_file()])
    print(dataset, 'panel and complete reference coverage verified')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dataset', choices=['favorita', 'm5', 'rossmann', 'rohlik'], required=True)
    parser.add_argument('--raw-root', type=Path, required=True,
                        help='Directory containing favorita/, m5/, rossmann/, and rohlik/ raw CSV folders')
    parser.add_argument('--reference-root', type=Path, required=True,
                        help='Dataset output folder produced by the original reference-stage runner')
    parser.add_argument('--out', type=Path, required=True)
    args = parser.parse_args()
    prepare(args.dataset, args.raw_root, args.reference_root, args.out)


if __name__ == '__main__':
    main()
